    {
      "claim": "All L1 gold contexts report human absolute oral F values at or above 32%, with most values between 50% and 90%; no L1 gold context supports F < 20%.",
      "card_ids": ["C01","C03","C06","C09","C15","C17","C27","C30","C33"]
