    },
    {
      "claim": "L3 oral AUC/Cmax records for risperidone (M01) and paliperidone/9-hydroxyrisperidone (M05), which share the 6-fluoro-1,2-benzisoxazol-3-yl piperidine core with the query, demonstrate measurable systemic exposure after oral dosing (e.g., risperidone AUC0-inf 26.19-111.38 ng·h/mL after 1-2 mg; paliperidone ER AUC0-24 67.5 ng·h/mL after 3 mg and 199 ng·h/mL at steady state).",
      "card_ids": ["C101","C97","C113","C99","C129","C144","C117","C131","C126","C139","C128","C118","C115","C120","C104","C95","C140"]
    },
    {
      "claim": "No L3 record provides an absolute F value or any affirmative threshold-relevant evidence of F < 20% for the query or its close analogs; the records lack IV comparators and therefore cannot quantify F.",
      "card_ids": ["C101","C97","C113","C99","C129","C144","C117","C131","C126","C139","C128","C118","C115","C120","C104","C95","C140"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C101","C97","C113","C99","C129","C144","C117","C131","C126","C139","C128","C118","C115","C120","C104","C95","C140"]
    }
  ],
  "evidence_gaps": [
    "No direct iloperidone-specific absolute F measurement is present; the decision relies on transferred contexts and structural analogy.",
    "No IV-reference absolute F measurement is available for the query molecule itself.",
    "L3 oral AUC/Cmax records lack IV comparators, so they cannot quantify absolute F.",
    "Query-specific food-effect, formulation, dose-response, and first-pass metabolism data are not provided.",
    "Structural similarity to M01/M05 is qualitative; transfer_likelihood is a relevance signal, not an experimental result.",
    "The mixed physicochemical prior (low neutral fraction 0.08, high logP 4.83) is not resolved by direct query data."
  ],
  "decision_summary": "L3 oral exposure records for the structurally related risperidone/paliperidone series demonstrate measurable oral absorption for the shared benzisoxazole-piperidine scaffold but do not provide absolute F values or any affirmative sub-20% evidence. The prior high prediction based on L1/L2 human gold contexts remains supported; no new card contradicts F >= 20%, so the prediction remains high and is strengthened."
}

